import 'package:flutter_test/flutter_test.dart';
import 'package:andi_carpeta/finance/intents/finance_intent.dart';
import 'package:andi_carpeta/finance/intents/finance_repository.dart';
import 'support/finance_atomic_fixture.dart';
Map<String,Object?> history()=>{'teamId':'team','managerId':'manager','name':'Trip','closed':false,'startDate':DateTime.utc(2026,10,1),'receivedDeparture':25.0,'receivedDuring':10.0,'receivedEntries':<Object?>[]};
FinanceIntent receipt(int n,{int revision=0,String actor='manager',String collection='settlements',double amount=200})=>FinanceIntent(operationId:n.toRadixString(16).padLeft(32,'0'),actorUid:actor,teamId:'team',collection:collection,documentId:collection=='finance'?'team':'trip',baseRevision:revision,kind:FinanceIntentKind.receipt,changes:{'kind':'departure','amount':amount,'method':'Cash','fromName':'Synthetic payer','date':DateTime.utc(2026,10,15)});
void main(){
 for(final legacy in [false,true]){
  final path=legacy?'finance/team':'settlements/trip';final collection=legacy?'finance':'settlements';
  test('atomic receipt preserves opening history legacy=$legacy',()async{final db=FinanceAtomicFixture()..seed(path,history());final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);final r=await repo.execute(receipt(1,collection:collection));expect(r.status,FinanceIntentStatus.confirmed);expect(db.documents[path]!['receivedDeparture'],225);expect(db.documents[path]!['receivedDuring'],10);expect(db.documents[path]!['receivedOpeningDeparture'],25);expect(db.writes,2);});
  test('20 competing copies of same intent apply once legacy=$legacy',()async{final db=FinanceAtomicFixture()..seed(path,history());final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);final i=receipt(1,collection:collection);final results=await Future.wait(List.generate(20,(_)=>repo.execute(i)));expect(results.every((r)=>r.status==FinanceIntentStatus.confirmed),true);expect(db.writes,2);expect(db.documents[path]!['receivedEntries'],hasLength(1));expect(db.callbacks,greaterThan(20));});
  test('two different same-revision intents conflict without losing history legacy=$legacy',()async{final db=FinanceAtomicFixture()..seed(path,history());final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);final results=await Future.wait([repo.execute(receipt(1,collection:collection)),repo.execute(receipt(2,collection:collection))]);expect(results.where((r)=>r.status==FinanceIntentStatus.confirmed),hasLength(1));expect(results.where((r)=>r.status==FinanceIntentStatus.conflict),hasLength(1));expect(db.writes,2);});
  test('two legitimate equal amounts at successive revisions both apply legacy=$legacy',()async{final db=FinanceAtomicFixture()..seed(path,history());final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);await repo.execute(receipt(1,collection:collection));await repo.execute(receipt(2,revision:1,collection:collection));expect(db.documents[path]!['receivedDeparture'],425);expect(db.documents[path]!['receivedEntries'],hasLength(2));expect(db.writes,4);});
  test('commit then timeout reconciles without writes and explicit replay is no-op legacy=$legacy',()async{final db=FinanceAtomicFixture()..seed(path,history())..commitThenThrow=true;final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);final i=receipt(1,collection:collection);expect((await repo.execute(i)).status,FinanceIntentStatus.uncertain);expect(db.writes,2);expect((await repo.reconcile(i)).status,FinanceIntentStatus.confirmed);expect(db.writes,2);db.commitThenThrow=false;expect((await repo.execute(FinanceIntent.decode(i.encode()))).replayed,true);expect(db.writes,2);});
 }
 for(final mode in ['absent','cached','pending']){test('reconciliation $mode never invents confirmation or writes',()async{final db=FinanceAtomicFixture()..seed('settlements/trip',history());final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);final i=receipt(1);if(mode!='absent')await repo.execute(i);db.fromCache=mode=='cached';db.pending=mode=='pending';final writes=db.writes;expect((await repo.reconcile(i)).status,FinanceIntentStatus.uncertain);expect(db.writes,writes);});}
 test('same ID with changed request conflicts',()async{final db=FinanceAtomicFixture()..seed('settlements/trip',history());final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);await repo.execute(receipt(1));expect((await repo.execute(receipt(1,amount:201))).status,FinanceIntentStatus.conflict);expect(db.writes,2);});
 test('timeout before commit remains uncertain with no automatic second call',()async{final db=FinanceAtomicFixture()..seed('settlements/trip',history())..failBeforeCommit=true;final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);expect((await repo.execute(receipt(1))).status,FinanceIntentStatus.uncertain);expect(db.writes,0);expect(db.calls,1);});
 test('wrong owner is rejected before reading or writing',()async{final db=FinanceAtomicFixture();final repo=FinanceRepository(port:db,ownerUid:'B',sessionIsCurrent:()=>true);expect((await repo.execute(receipt(1))).status,FinanceIntentStatus.rejectedBeforeWrite);expect(db.calls,0);});
 test('revocation inside transaction causes zero writes',()async{final db=FinanceAtomicFixture()..seed('settlements/trip',history());var checks=0;final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>++checks<3);expect((await repo.execute(receipt(1))).status,FinanceIntentStatus.rejectedBeforeWrite);expect(db.writes,0);});
 test('late commit after revocation is uncertain, cannot certify successor',()async{final db=FinanceAtomicFixture()..seed('settlements/trip',history());var active=true;db.beforeCommit=()async{active=false;};final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>active);expect((await repo.execute(receipt(1))).status,FinanceIntentStatus.uncertain);expect(db.writes,2);expect((await repo.reconcile(receipt(1))).status,FinanceIntentStatus.uncertain);expect(db.serverReads,0);});
 test('inconsistent legacy totals require review rather than fabricated transfer',()async{final h=history();h['receivedEntries']=[{'id':'old','kind':'departure','amount':100.0}];final db=FinanceAtomicFixture()..seed('settlements/trip',h);final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);expect((await repo.execute(receipt(1))).code,'finance_history_requires_review');expect(db.writes,0);});
 test('closed settlement cannot receive money',()async{final db=FinanceAtomicFixture()..seed('settlements/trip',history()..['closed']=true);final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);expect((await repo.execute(receipt(1))).status,FinanceIntentStatus.rejectedBeforeWrite);expect(db.writes,0);});
 test('newer Admin-like revision prevents stale receipt',()async{final db=FinanceAtomicFixture()..seed('settlements/trip',history()..['revision']=2);final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);expect((await repo.execute(receipt(1))).status,FinanceIntentStatus.conflict);expect(db.writes,0);});
 for(final kind in [FinanceIntentKind.edit,FinanceIntentKind.close]){test('$kind serializes and preserves unrelated financial history',()async{final db=FinanceAtomicFixture()..seed('settlements/trip',history());final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);final i=FinanceIntent(operationId:'a'*32,actorUid:'manager',teamId:'team',collection:'settlements',documentId:'trip',baseRevision:0,kind:kind,changes:kind==FinanceIntentKind.edit?{'name':'Revised'}:{'closed':true,'endDate':DateTime.utc(2026,10,15)});expect((await repo.execute(i)).status,FinanceIntentStatus.confirmed);expect(db.documents['settlements/trip']!['receivedDeparture'],25);expect((await repo.execute(i)).replayed,true);expect(db.writes,2);});}
 test('create has stable target and cannot overwrite an existing document',()async{final db=FinanceAtomicFixture();final repo=FinanceRepository(port:db,ownerUid:'manager',sessionIsCurrent:()=>true);final i=FinanceIntent(operationId:'a'*32,actorUid:'manager',teamId:'team',collection:'settlements',documentId:'trip',baseRevision:0,kind:FinanceIntentKind.create,changes:{'name':'Trip','startDate':DateTime.utc(2026,10,1),'managerId':'manager','perDiemRate':50,'createdAt':DateTime.utc(2026,10,1)});expect((await repo.execute(i)).status,FinanceIntentStatus.confirmed);expect((await repo.execute(FinanceIntent.decode(i.encode()))).replayed,true);expect(db.writes,2);});
}
